selector_to_html = {"a[href=\"#environment-for-build-and-run\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Environment for build and run<a class=\"headerlink\" href=\"#environment-for-build-and-run\" title=\"Link to this heading\">#</a></h2><h3>1.1 System dependencies<a class=\"headerlink\" href=\"#system-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../user_guide/use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-CPU<a class=\"headerlink\" href=\"#use-tle-cpu\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-CPU. TLE-CPU is available on trition_3.3.x branch.</p><p>TLE-CPU allows a unified programming paradigm covering diverse edge-side CPU compute power. Extends TLE\u2019s philosophy of \u201clayering hardware deep optimizations on top of <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code>\u201d to CPUs. Targeting the fragmented CPU ecosystem for edge AI (Arm64 / RISC-V / x86 with multiple coexisting ISAs), it uses the same Triton programming model and integration framework to support diverse ISAs: programming model and correctness are shared across ISAs (plain Triton lands on any ISA via LLVM), while each ISA\u2019s high-performance implementation (intrinsic / C runtime) is contributed separately. Model code is routed to the corresponding ISA implementation through the operator library (FlagGems) vendor dispatch, eliminating the need to be aware of the specific ISA. The differences between CPU and GPU dictate that it requires an independent extension surface:</p>", "a[href=\"#q-runtime-reports-version-glibc-glibcxx-not-found\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q: Runtime reports version GLIBC / GLIBCXX not found?<a class=\"headerlink\" href=\"#q-runtime-reports-version-glibc-glibcxx-not-found\" title=\"Link to this heading\">#</a></h3><p>A: Check the versions supported by your environment and LD_PRELOAD if needed (aarch64 paths):</p>", "a[href=\"#build-from-source\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Build from source<a class=\"headerlink\" href=\"#build-from-source\" title=\"Link to this heading\">#</a></h3><p>Three steps: <strong>clone FlagTree \u2192 wire up flagtree-cpu via the helper script \u2192 build FlagTree</strong>.</p>", "a[href=\"#q-kernel-compilation-fails-with-kernel-s-error-junk-at-end-of-line-first-unrecognized-character-is\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q: kernel compilation fails with <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s:</span> <span class=\"pre\">Error:</span> <span class=\"pre\">junk</span> <span class=\"pre\">at</span> <span class=\"pre\">end</span> <span class=\"pre\">of</span> <span class=\"pre\">line,</span> <span class=\"pre\">first</span> <span class=\"pre\">unrecognized</span> <span class=\"pre\">character</span> <span class=\"pre\">is</span> <span class=\"pre\">\\</span></code>\u201d``?<a class=\"headerlink\" href=\"#q-kernel-compilation-fails-with-kernel-s-error-junk-at-end-of-line-first-unrecognized-character-is\" title=\"Link to this heading\">#</a></h3><p>A: <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGTREE_BACKEND=cpu</span></code> is not exported in the current shell. It is not only a build-time switch \u2014 runtime JIT compilation of <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s</span></code> also depends on it (it enables stripping of LLVM <code class=\"docutils literal notranslate\"><span class=\"pre\">.file</span></code>/<code class=\"docutils literal notranslate\"><span class=\"pre\">.loc</span></code> debug directives that the GNU assembler rejects, plus the ARM <code class=\"docutils literal notranslate\"><span class=\"pre\">-march</span></code> flags). Export it and re-run.</p>", "a[href=\"#source-free-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Source-free installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p>\u26a0\ufe0f There is no prebuilt wheel for the ARM64 cpu backend yet; build from source per 2.2 below.</p>", "a[href=\"#q-import-triton-language-extra-cpu-tle-ops-fails-with-no-module-named\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q: <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">triton.language.extra.cpu.tle_ops</span></code> fails with \u201cNo module named \u2026\u201d?<a class=\"headerlink\" href=\"#q-import-triton-language-extra-cpu-tle-ops-fails-with-no-module-named\" title=\"Link to this heading\">#</a></h3><p>A: The Step 2 symlinks are incomplete. Re-run <code class=\"docutils literal notranslate\"><span class=\"pre\">bash</span> <span class=\"pre\">python/scripts/link_flagtree_cpu.sh</span></code> \u2014 it is idempotent and exits non-zero if any expected symlink fails to resolve.</p>", "a[href=\"#create-a-virtualenv-and-install-pytorch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 Create a virtualenv and install PyTorch<a class=\"headerlink\" href=\"#create-a-virtualenv-and-install-pytorch\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#installation-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Installation Commands<a class=\"headerlink\" href=\"#installation-commands\" title=\"Link to this heading\">#</a></h2><h3>2.1 Source-free installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p>\u26a0\ufe0f There is no prebuilt wheel for the ARM64 cpu backend yet; build from source per 2.2 below.</p>", "a[href=\"#system-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 System dependencies<a class=\"headerlink\" href=\"#system-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#q-a\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q&amp;A<a class=\"headerlink\" href=\"#q-a\" title=\"Link to this heading\">#</a></h2><h3>Q: Performance is only half on a big.LITTLE SoC?<a class=\"headerlink\" href=\"#q-performance-is-only-half-on-a-big-little-soc\" title=\"Link to this heading\">#</a></h3><p>A: On heterogeneous SoCs (e.g. Cortex-A720 big + A520 little), always pin to the <strong>big cores only</strong> with <code class=\"docutils literal notranslate\"><span class=\"pre\">taskset</span></code> \u2014 little cores entering the OMP thread pool stall on the barrier and cost ~2x overall. Also set the governor to performance:</p>", "a[href=\"#q-performance-is-only-half-on-a-big-little-soc\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q: Performance is only half on a big.LITTLE SoC?<a class=\"headerlink\" href=\"#q-performance-is-only-half-on-a-big-little-soc\" title=\"Link to this heading\">#</a></h3><p>A: On heterogeneous SoCs (e.g. Cortex-A720 big + A520 little), always pin to the <strong>big cores only</strong> with <code class=\"docutils literal notranslate\"><span class=\"pre\">taskset</span></code> \u2014 little cores entering the OMP thread pool stall on the barrier and cost ~2x overall. Also set the governor to performance:</p>", "a[href=\"#testing-and-validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Testing and validation<a class=\"headerlink\" href=\"#testing-and-validation\" title=\"Link to this heading\">#</a></h2><p>\u26a0\ufe0f Before running anything that JIT-compiles kernels (the validation scripts below, and model inference in general), export <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGTREE_BACKEND=cpu</span></code> \u2014 at runtime it enables the ARM <code class=\"docutils literal notranslate\"><span class=\"pre\">-march</span></code> flags, OpenMP linkage and GCC-assembler compatibility handling for the emitted <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s</span></code>:</p>", "a[href=\"#install-on-arm64-cpu\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install on Arm64 CPU<a class=\"headerlink\" href=\"#install-on-arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>Before installing the FlagTree on Arm64 CPU, please read the following notes:</p>", "a[href=\"#llvm-toolchain\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.3 LLVM toolchain<a class=\"headerlink\" href=\"#llvm-toolchain\" title=\"Link to this heading\">#</a></h3><p>If <code class=\"docutils literal notranslate\"><span class=\"pre\">oaitriton.blob.core.windows.net</span></code> is reachable, the LLVM toolchain is fetched automatically on the first build (step 2.2 Step 3) according to <code class=\"docutils literal notranslate\"><span class=\"pre\">cmake/llvm-hash.txt</span></code> (a66376b0) and cached under <code class=\"docutils literal notranslate\"><span class=\"pre\">~/.triton/llvm/</span></code> \u2014 <strong>no manual step needed</strong>.</p><p>For restricted networks, download manually (note the <strong>arm64</strong> package, for Triton 3.3):</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
